  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animorphe-(Alchimiste).html&quot; title=&quot;Animorphe&quot;&gt;Animorphe&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artificier-Des-Profondeurs-(Alchimiste).html&quot; title=&quot;Artificier des profondeurs&quot;&gt;Artificier des profondeurs&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Svirfneblin-(Race).html&quot; title=&quot;Les svirfneblins&quot;&gt;Svirfneblin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brasseur-D&#233;pines-(Alchimiste).html&quot; title=&quot;Brasseur d&amp;#39;&#233;pines&quot;&gt;Brasseur d&#39;&#233;pines&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;Demi-elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chercheur-Dœnopion-(Alchimiste).html&quot; title=&quot;Chercheur visionnaire&quot;&gt;Chercheur visionnaire&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Enrag&#233;-(Alchimiste).html&quot; title=&quot;Chimiste enrag&#233;&quot;&gt;Chimiste enrag&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Inspir&#233;-(Alchimiste).html&quot; title=&quot;Chimiste inspir&#233;&quot;&gt;Chimiste inspir&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chimiste-Spirituel-(Alchimiste).html&quot; title=&quot;Chimiste spirituel&quot;&gt;Chimiste spirituel&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chirurgien-(Alchimiste).html&quot; title=&quot;Chirurgien&quot;&gt;Chirurgien&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collectionneur-(Alchimiste).html&quot; title=&quot;Collectionneur&quot;&gt;Collectionneur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ectochimiste-(Alchimiste).html&quot; title=&quot;Ectochimiste&quot;&gt;Ectochimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Explorateur-De-Cryptes-(Alchimiste).html&quot; title=&quot;Explorateur de cryptes&quot;&gt;Explorateur de cryptes&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grenadier-(Alchimiste).html&quot; title=&quot;Grenadier&quot;&gt;Grenadier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Homonculiste-(Alchimiste).html&quot; title=&quot;Homonculiste &quot;&gt;Homonculiste&lt;/a&gt; (FF)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interrogateur-(Alchimiste).html&quot; title=&quot;Interrogateur&quot;&gt;Interrogateur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inventeur-Alchimiste-(Alchimiste).html&quot; title=&quot;Inventeur alchimiste&quot;&gt;Inventeur alchimiste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Clones-(Alchimiste).html&quot; title=&quot;Ma&#238;tre des clones&quot;&gt;Ma&#238;tre des clones&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maraudeur-Ail&#233;-(Alchimiste).html&quot; title=&quot;Maraudeur ail&#233;&quot;&gt;Maraudeur ail&#233;&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-(Alchimiste).html&quot; title=&quot;M&#233;tamorphe&quot;&gt;M&#233;tamorphe&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Peste-(Alchimiste).html&quot; title=&quot;Porte-peste&quot;&gt;Porte-peste&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;Homme-rat&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychonaute-(Alchimiste).html&quot; title=&quot;Psychonaute&quot;&gt;Psychonaute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrobombardier-(Alchimiste).html&quot; title=&quot;Pyrobombardier&quot;&gt;Pyrobombardier&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelin-(Race).html&quot; title=&quot;Les gobelins&quot;&gt;Gobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;animateur-(Alchimiste).html&quot; title=&quot;R&#233;animateur&quot;&gt;R&#233;animateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saboteur-(Alchimiste).html&quot; title=&quot;Saboteur&quot;&gt;Saboteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sapeur-Alchimique-(Alchimiste).html&quot; title=&quot;Sapeur alchimique&quot;&gt;Sapeur alchimique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trappeur-Alchimique-(Alchimiste).html&quot; title=&quot;Trappeur alchimique&quot;&gt;Trappeur alchimique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vivisectioniste-(Alchimiste).html&quot; title=&quot;Vivisectioniste&quot;&gt;Vivisectioniste&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Les Ectochimistes &#233;tudient les effets de l’alchimie sur l’&#226;me et l’esprit, et se sp&#233;cialisent dans le combat contre les fant&#244;mes et autres cr&#233;atures intangibles.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Un Ectochimiste ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) &#224; sa liste de comp&#233;tences de classe, ce qui modifie la liste de comp&#233;tences de classe de l’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Enduit ectoplasmique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Enduit_ectoplasmique_Sur_1&quot; href=&quot;#Enduit_ectoplasmique_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Un Ectochimiste peut traiter par alchimie une arme de corps &#224; corps pour qu’elle inflige des d&#233;g&#226;ts normaux aux cr&#233;atures intangibles. Ce traitement n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions.html#COMPLEXE&quot; title=&quot;Les actions en combat&quot;&gt;action complexe&lt;/a&gt; et reste efficace jusqu’&#224; la prochaine utilisation de l’arme pour effectuer une attaque. Un ectochimiste peut utiliser cette aptitude un nombre de fois par jour &#233;gal &#224; son niveau d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;. Cette aptitude remplace celle de &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#BOMBES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;bombes&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;T&#234;te froide (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;T&#234;te_froide_Ext_2&quot; href=&quot;#T&#234;te_froide_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt; 
Un ectochimiste de niveau 2 b&#233;n&#233;ficie d’un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort.html#MORT&quot; title=&quot;Cr&#233;er un sort&quot;&gt;effets de mort&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Terreur-(Capacit&#233;).html&quot; title=&quot;Terreur (Mag ou Sur)&quot;&gt;terreur&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;&#233;nergie n&#233;gative&lt;/a&gt;. Ce bonus passe &#224; +4 au niveau 5 et &#224; +6 au niveau 8. Cette aptitude remplace celle de &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;r&#233;sistance au poison&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ectochimie avanc&#233;e (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Ectochimie_avanc&#233;e_Sur_3&quot; href=&quot;#Ectochimie_avanc&#233;e_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une arme sur laquelle est appliqu&#233; l’enduit ectoplasmique d’un ectochimiste de niveau 2 inflige &#233;galement des d&#233;g&#226;ts normaux aux &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-Dapparitions.html&quot; title=&quot;Exemples d&amp;#39;apparitions&quot;&gt;apparitions&lt;/a&gt;. Cette aptitude remplace celle d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#UTILISATIONDUPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;utilisation des poisons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ectochimie rapide (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Ectochimie_rapide_Sur_4&quot; href=&quot;#Ectochimie_rapide_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un ectochimiste de niveau 6 peut appliquer l’enduit ectoplasmique sur l’une de ses armes par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions.html#RAPIDE&quot; title=&quot;Les actions en combat&quot;&gt;action rapide&lt;/a&gt;. Une fois appliqu&#233; sur une arme mani&#233;e par l’ectochimiste, l’enduit ectoplasmique reste efficace pendant un nombre d’attaques &#233;gal au modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; de l’ectochimiste (pendant une attaque au minimum). Cette aptitude remplace celle d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#EMPOISONNEMENTRAPIDE&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;empoisonnement rapide&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pi&#232;ge &#224; fant&#244;me (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pi&#232;ge_&#224;_fant&#244;me_Sur_5&quot; href=&quot;#Pi&#232;ge_&#224;_fant&#244;me_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un ectochimiste de niveau 8 peut lancer un pi&#232;ge pour capturer une cr&#233;ature intangible dont le nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;D&#233;s de Vie&lt;/a&gt; est &#233;gal ou inf&#233;rieur au niveau d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; du personnage. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions.html#SIMPLE&quot; title=&quot;Les actions en combat&quot;&gt;action simple&lt;/a&gt;, l’ectochimiste peut d&#233;penser une utilisation de l’enduit ectoplasmique pour enduire l’int&#233;rieur d’un r&#233;cipient et le lancer sur une cr&#233;ature intangible en effectuant une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDECONTACT&quot; title=&quot;Valeurs de combat&quot;&gt;attaque de contact&lt;/a&gt;
&#224; distance. Si l’attaque touche, la cr&#233;ature doit r&#233;ussir un jet de Volont&#233; pour &#233;chapper au pi&#232;ge (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + la moiti&#233; du niveau d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; du personnage + son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;). Si la cr&#233;ature rate son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt;, elle se retrouve s&#233;questr&#233;e dans le r&#233;cipient jusqu’&#224; ce que quelqu’un le casse ou l’ouvre. Le pi&#232;ge &#224; fant&#244;me r&#233;siste automatiquement &#224; l’impact du lancer sur la cr&#233;ature intangible mais il poss&#232;de par ailleurs la m&#234;me durabilit&#233; que le r&#233;cipient utilis&#233; (une bouteille en verre, par exemple, poss&#232;de une solidit&#233; de 5 et 1 point de r&#233;sistance). Cette aptitude remplace la &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#DECOUVERTES&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;d&#233;couverte&lt;/a&gt; que l’alchimiste obtient au niveau 8.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Analyse ectochimique (Mag)&lt;a class=&quot;headeranchor&quot; id=&quot;Analyse_ectochimique_Mag_6&quot; href=&quot;#Analyse_ectochimique_Mag_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un ectochimiste de niveau 10 peut appliquer ses solutions alchimiques pour collecter des informations &#233;sot&#233;riques sur une zone hant&#233;e, informations que l’on ne peut normalement collecter qu’&#224; l’aide de &lt;a class=&quot;pagelink&quot; href=&quot;Divination.html&quot; title=&quot;Divination&quot;&gt;divinations&lt;/a&gt;. Ce processus prend 10 minutes et n&#233;cessite la d&#233;pense d’une utilisation d’enduit ectoplasmique. Cette aptitude produit le m&#234;me effet
qu’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Apparitions.html&quot; title=&quot;Communication avec les apparitions&quot;&gt;communication avec les apparitions&lt;/a&gt;&lt;/i&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; &#233;gal &#224; 10 + la moiti&#233; du niveau d’ectochimiste + le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; de l’ectochimiste, et un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; &#233;gal au niveau d’ectochimiste. Le personnage effectue une analyse pour obtenir des r&#233;ponses &#224; ses questions et ne s’adresse pas directement &#224; l’apparition, voil&#224; pourquoi il oppose le r&#233;sultat de son test d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (alchimie), et non de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;, aux &#233;ventuels tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; effectu&#233;s par l’esprit afin de le tromper. Cette aptitude remplace celle d’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html#RESISTPOISON&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;immunit&#233; contre les poisons&lt;/a&gt;.
